var n=`0311-mekitsi`;var t=`world-0311`;var a=`BG`;var o=`eastern-europe`;var r=4;var s=43;var l={en:`Mekitsi`,ua:`Мекіці`};var g={en:`A traditional Bulgaria dish made with all-purpose flour, plain yogurt, chicken egg, baking soda. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Болгарія. Основні інгредієнти: пшеничне борошно універсальне, натуральний йогурт, куряче яйце, харчова сода. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`all-purpose-flour`,430,`g`],[`plain-yogurt`,220,`g`],[`chicken-egg`,2,`pcs`],[`baking-soda`,6,`g`],[`table-salt`,3,`g`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 20 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 20 хвилин.`,t:[`rapid-chilling`],m:20,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 13 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 13 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:13,i:[[`sunflower-oil`,600,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`powdered-sugar`,50,`g`]]}];var u={slug:n,id:t,country:`BG`,region:o,servings:4,minutes:43,title:l,text:g,steps:d};export{a as country,u as default,t as id,s as minutes,o as region,r as servings,n as slug,d as steps,g as text,l as title};